//! Completion data and ranking for LaTeX (ARCHITECTURE §5 "Completion").
//!
//! - **L1**, built in: static tables generated by `cargo run -p xtask -- gen-completion` into
//!   `src/generated.rs` from the TeXstudio word lists (`data/raw/cwl`), the unicode-math symbol
//!   table (`data/raw/umath_map.tsv`) and Lemma's own supplements (`data/completion`).
//!   [`CompletionDb::builtin`] loads the kernel, amsmath, amssymb and amsthm.
//! - **L2**, per package: [`CompletionDb::load_packages`] adds the tables of the packages a
//!   project loads (and the packages those load). Every word list is compiled; the core
//!   packages' tables are static, every other package's are one zstd frame of
//!   `src/packages.zst` (embedded), decompressed the first time a project loads the package.
//! - **L3**, the project: user macros, environments, labels with their `.aux` numbers and
//!   bibliography entries come from the [`ProjectIndex`](lemma_syntax::ProjectIndex); words from the user's dictionaries and
//!   the project's text come from a [`WordList`].
//!
//! [`Completer::complete`] picks the sources from the context at the cursor and ranks them with
//! frizbee (the matcher of blink.cmp) plus fixed bonuses.
//!
//! # Use from the completion provider
//!
//! - **Tables:** [`CompletionDb::builtin`], then [`CompletionDb::load_packages`] with
//!   `ProjectIndex::packages()` and `class-<name>` for the root's [`document_class`] whenever
//!   the index changes (loading again is cheap).
//! - **Words:** [`WordList::from_text`] with the user's word lists (`spell.word_lists`); clone
//!   it and add the project's sources with [`WordList::add_project_texts`] on idle (all at once:
//!   one merge into the list).
//! - **Files:** [`Completer::set_files`] with the project's files, relative to the root.
//! - **Triggers:** `\`, `{` after a command whose argument the scanner classifies (or
//!   [`CompletionDb::arg_kind`] knows), `,` in reference and citation lists, and words.
//! - **Context:** inside a command name, pass the context at its backslash (see
//!   [`CompletionRequest`]) so that commands are filtered by math or text mode.
//! - **Accepting:** replace `line_before[req.replace_start()..]` with [`Item::insert`] (one undo
//!   step; snippets through the snippet driver), then call [`Completer::record_accepted`].
//!
//! ```
//! use lemma_complete::{CompletionDb, CompletionRequest, Completer, Insert, WordList};
//! use lemma_snippets::SnippetSet;
//! use lemma_syntax::{Context, ProjectIndex};
//!
//! let db = CompletionDb::builtin();
//! let snippets = SnippetSet::defaults();
//! let (index, words) = (ProjectIndex::default(), WordList::default());
//! let mut completer = Completer::new();
//!
//! // The cursor is after `\fr` in inline math; the context is the one at the backslash.
//! let line_before = r"$x = \fr";
//! let ctx = Context::Math { display: false, env: None };
//! let req = CompletionRequest::new(&ctx, line_before);
//! let mut items = Vec::new();
//! completer.complete(&db, &snippets, &index, &words, &req, &mut items);
//!
//! assert_eq!(items[0].label, r"\frac");
//! assert_eq!(&line_before[req.replace_start()..], r"\fr");
//! assert!(matches!(items[0].insert, Insert::Snippet(_))); // \frac{$1}{$2}
//! completer.record_accepted(&items[0].label);
//! ```

mod complete;
mod db;
#[rustfmt::skip]
mod generated;
mod request;
mod tables;
mod text;
mod words;

pub use complete::{Completer, MAX_ITEMS};
pub use db::{BUILTIN_PACKAGES, CompletionDb, document_class};
pub use request::CompletionRequest;
pub use tables::glyph_for;
pub use words::WordList;

use lemma_snippets::Chunk;

/// Where a command may be completed.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Mode {
    Any,
    MathOnly,
    TextOnly,
}

/// Static command entry generated by xtask into `src/generated.rs` (.rodata).
#[derive(Clone, Copy, Debug)]
pub struct CmdEntry {
    /// The name without the backslash (`frac`, `section*`).
    pub name: &'static str,
    /// Inserted text in lemma snippet body syntax, backslash included (`\frac{$1}{$2}`).
    pub snippet: &'static str,
    pub mode: Mode,
    /// The word list it comes from (`latex-document`, `amsmath`, `class-amsart`, …).
    pub package: &'static str,
    /// The Unicode glyph of a symbol command (`\alpha` → α).
    pub glyph: Option<char>,
}

/// Static environment entry generated by xtask.
#[derive(Clone, Copy, Debug)]
pub struct EnvEntry {
    pub name: &'static str,
    /// What goes between `\begin{name}` and `\end{name}`, in lemma snippet body syntax: the
    /// arguments as tab stops on the `\begin` line, then an indented content line holding `$0`
    /// (with `\item` for lists), e.g. `{$1}\n  $0\n` for `alignat`. See
    /// [`CompletionDb::env_snippet`].
    pub body: &'static str,
    /// The environment starts math mode (`#\math` in the word list: `align`, `equation`, …).
    pub math: bool,
    pub package: &'static str,
}

/// The source of a completion item (decides its icon and ranking bonus).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ItemKind {
    Command,
    Environment,
    Snippet,
    Label,
    Citation,
    File,
    Package,
    UserMacro,
    Word,
}

/// What accepting an item inserts.
///
/// The text replaces `line_before[req.replace_start()..]` (see
/// [`CompletionRequest::replace_start`]): for commands and user macros that includes the
/// backslash, so the insertion starts with `\`. Snippets are not indented yet
/// (`lemma_snippets::with_indent`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Insert {
    Text(String),
    Snippet(Vec<Chunk>),
}

/// One completion proposal.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Item {
    /// What the popup shows and what [`Completer::record_accepted`] expects: `\frac`, `align`,
    /// `thm:main`, a citation key, a file name, a snippet trigger or a word.
    pub label: String,
    pub insert: Insert,
    pub kind: ItemKind,
    /// The argument signature and package (`{num}{den} · LaTeX`), a label's number and title,
    /// a citation's author, year and title, a user macro's definition, or a snippet's description.
    pub detail: Option<String>,
    /// The Unicode glyph (`\alpha` → α, a user's `\Z` defined as `\mathbb{Z}` → ℤ).
    pub glyph: Option<char>,
    /// The ranking score (frizbee score plus bonuses); items are sorted by it, best first.
    pub score: i32,
}
